type Op =
  | { kind: "get"; key: string }
  | { kind: "put"; key: string; value: number };

function run(op: Op, store: Store): number {
  switch (op.kind) {
    case "get": return store.read(op.key);
    case "put": return store.write(op.key, op.value);
    default: { const never: never = op; throw new Error(`unhandled ${never}`); }
  }
}
